--## MONITORS ###
--###############
-- See https://wiki.hyprland.org/Configuring/Monitors/

hl.monitor({
	output = "DP-2",
	mode = "2560x1440@270",
	position = "1440x800",
	scale = 1,
	vrr = 2,
})

hl.monitor({
	output = "HDMI-A-1",
	mode = "2560x1440@60",
	position = "0x0",
	scale = 1,
	transform = 3,
})

