--###################

--## KEYBINDINGSS ###

--###################

-- See https://wiki.hyprland.org/Configuring/Keywords/
local mainMod = "SUPER"
-- Sets "Windows" key as main modifier
-- Example binds, see https://wiki.hyprland.org/Configuring/Binds/ for more
hl.bind(mainMod .. " + " .. "RETURN", hl.dsp.exec_cmd("ghostty"))
hl.bind(mainMod .. " + " .. "Q", hl.dsp.window.close())
hl.bind(mainMod .. " + " .. "M", hl.dsp.exit())
hl.bind(mainMod .. " + " .. "E", hl.dsp.exec_cmd("thunar"))
-- bind = $mainMod, F, togglefloating,
hl.bind(mainMod .. " + " .. "F", hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + " .. "Space", hl.dsp.exec_cmd("rofi -show drun"))
hl.bind(mainMod .. " + " .. "P", hl.dsp.window.pseudo())

-- dwindle
-- bind = $mainMod, J, togglesplit, # dwindle
-- Move focus with mainMod + arrow keys
hl.bind("CTRL" .. " + " .. "h", hl.dsp.focus({ direction = "l" }))
hl.bind("CTRL" .. " + " .. "l", hl.dsp.focus({ direction = "r" }))
hl.bind("CTRL" .. " + " .. "k", hl.dsp.focus({ direction = "u" }))
hl.bind("CTRL" .. " + " .. "j", hl.dsp.focus({ direction = "d" }))
hl.bind("CTRL + SHIFT" .. " + " .. "h", hl.dsp.window.move({ direction = "l" }))
hl.bind("CTRL + SHIFT" .. " + " .. "l", hl.dsp.window.move({ direction = "r" }))
hl.bind("CTRL + SHIFT" .. " + " .. "k", hl.dsp.window.move({ direction = "u" }))
hl.bind("CTRL + SHIFT" .. " + " .. "j", hl.dsp.window.move({ direction = "d" }))

-- Switch workspaces with mainMod + [0-9]
hl.bind(mainMod .. " + " .. 1, hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + " .. 2, hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + " .. 3, hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + " .. 4, hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + " .. 5, hl.dsp.focus({ workspace = 5 }))
hl.bind(mainMod .. " + " .. 6, hl.dsp.focus({ workspace = 6 }))
hl.bind(mainMod .. " + " .. 7, hl.dsp.focus({ workspace = 7 }))
hl.bind(mainMod .. " + " .. 8, hl.dsp.focus({ workspace = 8 }))
hl.bind(mainMod .. " + " .. 9, hl.dsp.focus({ workspace = 9 }))
hl.bind(mainMod .. " + " .. 0, hl.dsp.focus({ workspace = 10 }))

-- Move active window to a workspace with mainMod + SHIFT + [0-9]
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 1, hl.dsp.window.move({ workspace = 1 }))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 2, hl.dsp.window.move({ workspace = 2 }))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 3, hl.dsp.window.move({ workspace = 3 }))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 4, hl.dsp.window.move({ workspace = 4 }))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 5, hl.dsp.window.move({ workspace = 5 }))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 6, hl.dsp.window.move({ workspace = 6 }))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 7, hl.dsp.window.move({ workspace = 7 }))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 8, hl.dsp.window.move({ workspace = 8 }))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 9, hl.dsp.window.move({ workspace = 9 }))
hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. 0, hl.dsp.window.move({ workspace = 10 }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + " .. "mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + " .. "mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + " .. "mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + " .. "mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Resize windows
local resizeUnit = 100
hl.bind(mainMod .. " + ALT + right", hl.dsp.window.resize({ x = resizeUnit, y = 0, relative = true }))
hl.bind(mainMod .. " + ALT + left", hl.dsp.window.resize({ x = -resizeUnit, y = 0, relative = true }))
hl.bind(mainMod .. " + ALT + up", hl.dsp.window.resize({ x = 0, y = -resizeUnit, relative = true }))
hl.bind(mainMod .. " + ALT + down", hl.dsp.window.resize({ x = 0, y = resizeUnit, relative = true }))

-- Type text currently in paste
hl.bind("ALT" .. " + " .. "V", hl.dsp.exec_cmd('wtype "$(wl-paste)"'))

-- Screenshot a selection and copy text to clipboard
hl.bind("PRINT", hl.dsp.exec_cmd('grim -g "$(slurp)"-| tesseract--| wl-copy'))
hl.bind(mainMod .. " + " .. "s", hl.dsp.exec_cmd("hyprshot -m region"))

-- Clipboard history
hl.bind(mainMod .. " + " .. "V", hl.dsp.exec_cmd("cliphist list| rofi -dmenu| cliphist decode| wl-copy"))

-- Reload Waybar configuration
hl.bind(mainMod .. " + " .. "W", hl.dsp.exec_cmd("pkill -SIGUSR2 waybar"))

-- Media controls
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { locked = true })
hl.bind(
	"XF86AudioPlay",
	hl.dsp.exec_cmd("curl -sf http://localhost:32500/player/playback/playPause || playerctl play-pause"),
	{ locked = true }
)
hl.bind(
	"XF86AudioNext",
	hl.dsp.exec_cmd("curl -sf http://localhost:32500/player/playback/skipNext || playerctl next"),
	{ locked = true }
)
hl.bind(
	"XF86AudioPrev",
	hl.dsp.exec_cmd("curl -sf http://localhost:32500/player/playback/skipPrevious || playerctl previous"),
	{ locked = true }
)

hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true })

